    # Select the 3x3 stencil crop with the simplest two-color structure.
    h, w = len(grid), len(grid[0])
    candidates = []
    for r in range(h - 2):
        for c in range(w - 2):
            crop = [row[c:c+3] for row in grid[r:r+3]]
            counts = {}
            for row in crop:
                for x in row:
                    counts[x] = counts.get(x, 0) + 1
            score = (len(counts), -max(counts.values()), -sum(n == 1 for n in counts.values()))
            candidates.append((score, r, c, crop, counts))
    _, r, c, crop, counts = min(candidates, key=lambda x: (x[0], x[1], x[2]))
    bg = max(counts, key=counts.get)
    return [[0 if x == bg else 8 for x in row] for row in crop]

